import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";

const fetchProducts = createAsyncThunk(
  "products/fetchProducts",
  async (params, { rejectWithValue }) => {
    const URL = "https://66e56d095cc7f9b6273d49bc.mockapi.io/occ";
    console.log(params);

    let {
      activeCategory: category = "",
      activeSortValue: sortBy = "",
      searchValue = "",
      page = 1,
    } = params;
    category = category === "All" ? "" : category;

    try {
      const response = await fetch(
        `${URL}/products?category=${category}&sortBy=${sortBy}&name=${searchValue}&page=${page}&limit=6`
      );
      const data = await response.json();
      if (data === "Not found") {
        return [];
      }
      return data;
    } catch (error) {
      return rejectWithValue("Something went wrong...");
    }
  }
);

const initialState = {
  items: [],
  loading: false,
  error: "",
  page: 1,
  isMoreItems: false,
  cache: {},
};

const productsSlice = createSlice({
  name: "products",
  initialState,
  reducers: {
    resetProducts(state) {
      state.page = 1;
      state.items = [];
      state.loading = true;
      state.isMoreItems = false;
    },
    loadFromCache(state, { payload }) {
      state.items = state.cache[payload.cacheKey].items;
      state.loading = false;
      state.isMoreItems = state.cache[payload.cacheKey].isMoreItems;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchProducts.pending, (state) => {
        state.error = "";
      })
      .addCase(fetchProducts.fulfilled, (state, { payload, meta }) => {
        const { activeCategory, activeSortValue, searchValue, page } = meta.arg;
        const cacheKey = `${activeCategory}_${activeSortValue}_${searchValue}`;
        state.cache[cacheKey] = {
          isMoreItems: payload.length === 6,
          items: page === 1 ? payload : [...state.items, ...payload],
        };

        state.page += 1;
        productsSlice.caseReducers.loadFromCache(state, {
          payload: { cacheKey },
        });
      })
      .addCase(fetchProducts.rejected, (state, { payload }) => {
        state.loading = false;
        state.error = payload;
      });
  },
});
export const { resetProducts, loadFromCache } = productsSlice.actions;
export const selectProducts = (store) => store.products;
export { fetchProducts };
export default productsSlice.reducer;
