import { createSlice } from "@reduxjs/toolkit";

const initialState = {
  categories: ["All", "Weekender", "Backpack", "Laptop"],
  activeCategory: "All",
  sortItems: [
    ["By most popular", "order"],
    ["From cheap", "price&order=asc"],
    ["From expensive", "price&order=desc"],
    ["By name", "name"],
  ],
  activeSortItem: ["By most popular", "order"],
  searchValue: "",
};

const filterSlice = createSlice({
  name: "filter",
  initialState,
  reducers: {
    setFilters(state, { payload }) {
      state.activeCategory = payload.activeCategory;
      state.activeSortItem = payload.sortItem;
      state.searchValue = payload.searchValue;
    },
    setActiveCategory(state, { payload }) {
      state.activeCategory = payload.category;
    },
    setActiveSortItem(state, { payload }) {
      state.activeSortItem = payload.item;
    },
    setSearchValue(state, { payload }) {
      state.searchValue = payload.value;
    },
  },
});

export const selectFilter = (store) => store.filter;

export const {
  setActiveCategory,
  setActiveSortItem,
  setSearchValue,
  setFilters,
} = filterSlice.actions;
export default filterSlice.reducer;
